//! Operations of the instruction-level ports beyond the chorus routines: fixed ALU flags,
//! conditional moves, shifts, `RECIPS`, `CLIP`, plus the pre-modify addressing forms
//! (`tools/fx_leslie_ops.py` is the Python twin; the routines are generated by
//! `tools/fx_mod2_rust_gen.py`).
//!
//! VERIFIED (`tools/fx_models.py`, `docs/research/fx-mod2-types.md`): flag semantics follow
//! `crates/nord-sharc/src/core/fixed_alu.rs` (AV signed overflow, AC carry out, `x - x` carries).
//! The `RECIPS` seed table is the measurement of `crates/nord-sharc/src/core/float_seeds.rs`
//! (5,644 inputs, max err 0). Floats are f32 here (the firmware keeps 40 bits).

use super::fw_pe::{Eff, Mem, Pe, P};
use super::fw_words::val;

/// Flag condition of an `IF cond` instruction.
#[derive(Clone, Copy)]
pub(super) enum Cond {
    Ne,
    Eq,
    Av,
    Ac,
    /// After a float compute: result positive (not negative, not zero).
    Gt,
    /// After a float compute: result negative and not zero.
    Lt,
    /// After a float compute: result negative or zero.
    Le,
}

/// `Ii += step` honouring the circular buffer `(len, base)`.
pub(super) fn dag_next(i: u32, step: u32, len: u32, base: u32) -> u32 {
    let next = i.wrapping_add(step);
    if len == 0 {
        next
    } else if (step as i32) >= 0 {
        if next >= base.wrapping_add(len) {
            next.wrapping_sub(len)
        } else {
            next
        }
    } else if next < base {
        next.wrapping_add(len)
    } else {
        next
    }
}

impl<M: Mem> Pe<M> {
    /// Pre-modify address `Ii + Mm` (no write back); wraps inside the circular buffer of `Ii`
    /// like the post-modify (VERIFIED: `ENS` against the oracle, `dm(m6,i6)` with `L6 = 0x200`).
    pub(super) fn plain(&self, i: usize, m: usize) -> u32 {
        dag_next(self.i[i], self.m[m], self.l[i], self.b[i])
    }

    /// `Ii` modified by an immediate, wrapping inside the circular buffer.
    pub(super) fn dmodi(&self, i: usize, step: u32) -> u32 {
        dag_next(self.i[i], step, self.l[i], self.b[i])
    }

    /// Whether `cond` holds in element `c` (from the flags of the last compute).
    fn holds(&self, cond: Cond, c: usize) -> bool {
        match cond {
            Cond::Ne => !self.az[c],
            Cond::Eq => self.az[c],
            Cond::Av => self.av[c],
            Cond::Ac => self.ac[c],
            Cond::Gt => !(self.an[c] || self.az[c]),
            Cond::Lt => self.an[c] && !self.az[c],
            Cond::Le => self.an[c] || self.az[c],
        }
    }

    /// `IF cond Rn = Rm`: the new pair where the condition holds, per element.
    pub(super) fn cond(&self, cond: Cond, old: P, new: P) -> P {
        [0, 1].map(|c| if self.holds(cond, c) { new[c] } else { old[c] })
    }

    #[allow(dead_code)] // used by the flanger routine, which has no wired stage yet
    /// One element of a conditional exchange (`IF cond Rx <-> Sy`).
    pub(super) fn cond_lane(&self, cond: Cond, lane: usize, old: u32, new: u32) -> u32 {
        if self.holds(cond, lane) {
            new
        } else {
            old
        }
    }
}

/// `Fl2` of a float result pair: negative / zero by value (denormals flushed).
pub(super) fn fl_float(p: P) -> Eff {
    Eff::Fl2(p.map(|w| val(w) < 0.0), p.map(|w| val(w) == 0.0))
}

/// `Fl2` of a fixed result pair.
pub(super) fn fl_int(p: P) -> Eff {
    Eff::Fl2(p.map(|w| (w as i32) < 0), p.map(|w| w == 0))
}

/// `Fl2` of `COMP(Fx, Fy)`: AN when `a < b`, AZ when equal (denormals flushed).
pub(super) fn fl_comp(a: P, b: P) -> Eff {
    Eff::Fl2(
        [0, 1].map(|c| val(a[c]) < val(b[c])),
        [0, 1].map(|c| val(a[c]) == val(b[c])),
    )
}

/// `Fl2` of `COMP(Rx, Ry)` of fixed-point registers: signed.
pub(super) fn fl_icomp(a: P, b: P) -> Eff {
    Eff::Fl2(
        [0, 1].map(|c| (a[c] as i32) < (b[c] as i32)),
        [0, 1].map(|c| a[c] == b[c]),
    )
}

/// `Rn = Rx * Ry (UUI)`: the low 32 bits of the unsigned product.
pub(super) fn imul(a: P, b: P) -> P {
    [0, 1].map(|c| a[c].wrapping_mul(b[c]))
}

/// `Rn = ASHIFT Rx BY Ry`: left when the amount is non-negative, else an arithmetic right shift.
pub(super) fn iashift(a: P, s: P) -> P {
    [0, 1].map(|c| {
        let n = s[c] as i32;
        if n >= 0 {
            a[c].checked_shl(n as u32).unwrap_or(0)
        } else {
            ((a[c] as i32) >> n.unsigned_abs().min(31)) as u32
        }
    })
}

/// `Fl4` of `a + b` (`sub = false`) or `a - b` per element: AN, AZ, AV (signed overflow) and AC
/// (carry out; `x - y` is `x + !y + 1`, so `x - x` carries).
pub(super) fn fl_add_sub(a: P, b: P, sub: bool) -> Eff {
    let mut out = [[false; 2]; 4];
    for c in 0..2 {
        let (x, y) = (a[c], b[c]);
        let (r, exact, carry) = if sub {
            (
                x.wrapping_sub(y),
                i64::from(x as i32) - i64::from(y as i32),
                x >= y,
            )
        } else {
            (
                x.wrapping_add(y),
                i64::from(x as i32) + i64::from(y as i32),
                u64::from(x) + u64::from(y) > u64::from(u32::MAX),
            )
        };
        out[0][c] = (r as i32) < 0;
        out[1][c] = r == 0;
        out[2][c] = i32::try_from(exact).is_err();
        out[3][c] = carry;
    }
    Eff::Fl4(out[0], out[1], out[2], out[3])
}

/// `Rn = Sm`: the pair with the elements exchanged.
pub(super) fn swap(a: P) -> P {
    [a[1], a[0]]
}

/// Signed maximum of two fixed-point words (`Rn = MAX(Rx, Ry)`).
pub(super) fn imax(a: P, b: P) -> P {
    [0, 1].map(|c| (a[c] as i32).max(b[c] as i32) as u32)
}

/// Signed minimum of two fixed-point words (`Rn = MIN(Rx, Ry)`).
pub(super) fn imin(a: P, b: P) -> P {
    [0, 1].map(|c| (a[c] as i32).min(b[c] as i32) as u32)
}

/// `Rn = FEXT Rx BY pos:len` (zero extended; `se` sign extends a field that fits the word).
pub(super) fn fext_p(a: P, pos: P, len: P, se: P) -> P {
    [0, 1].map(|c| {
        let (pos, len) = (pos[c], len[c]);
        let mut v = if pos < 32 { a[c] >> pos } else { 0 };
        if len < 32 {
            v &= (1u32 << len) - 1;
        }
        if se[c] != 0 && len > 0 && pos + len <= 32 && (v >> (len - 1)) & 1 == 1 {
            v |= !((1u32 << len) - 1);
        }
        v
    })
}

/// `Rn = FDEP Rx BY pos:len`: the low `len` bits of `a`, shifted to `pos`.
pub(super) fn fdep_p(a: P, pos: P, len: P) -> P {
    [0, 1].map(|c| {
        let field = if len[c] < 32 {
            a[c] & ((1u32 << len[c]) - 1)
        } else {
            a[c]
        };
        field.checked_shl(pos[c]).unwrap_or(0)
    })
}

pub(super) fn isub(a: P, b: P) -> P {
    [0, 1].map(|c| a[c].wrapping_sub(b[c]))
}

/// `Rn = LSHIFT Rx BY Ry`: a signed shift amount, left when non-negative.
pub(super) fn ishl(a: P, s: P) -> P {
    [0, 1].map(|c| {
        let n = s[c] as i32;
        if n >= 0 {
            a[c].checked_shl(n as u32).unwrap_or(0)
        } else {
            a[c].checked_shr(n.unsigned_abs()).unwrap_or(0)
        }
    })
}

/// `Fn = PASS Fx`: the float, denormals flushed.
pub(super) fn fpass(a: P) -> P {
    a.map(|w| val(w).to_bits())
}

/// `Fn = (Fx + Fy) / 2`.
pub(super) fn favg(a: P, b: P) -> P {
    [0, 1].map(|c| ((val(a[c]) + val(b[c])) / 2.0).to_bits())
}

/// `Fn = CLIP Fx BY Fy`: `x` limited to `+-|y|`.
pub(super) fn fclip(a: P, b: P) -> P {
    [0, 1].map(|c| {
        let (x, y) = (val(a[c]), val(b[c]).abs());
        x.clamp(-y, y).to_bits()
    })
}

/// VERIFIED: `RECIPS` seed fraction by the 7 MSBs of the input fraction (`float_seeds.rs`).
const RECIPS_SEED: [u8; 128] = [
    0xFF, 0xFC, 0xF8, 0xF4, 0xF0, 0xEC, 0xE8, 0xE4, 0xE0, 0xDE, 0xDA, 0xD6, 0xD4, 0xD0, 0xCC, 0xCA,
    0xC6, 0xC2, 0xC0, 0xBC, 0xBA, 0xB6, 0xB4, 0xB2, 0xAE, 0xAC, 0xA8, 0xA6, 0xA4, 0xA0, 0x9E, 0x9C,
    0x98, 0x96, 0x94, 0x92, 0x8E, 0x8C, 0x8A, 0x88, 0x86, 0x82, 0x80, 0x7E, 0x7C, 0x7A, 0x78, 0x76,
    0x74, 0x72, 0x70, 0x6E, 0x6C, 0x6A, 0x68, 0x66, 0x64, 0x62, 0x60, 0x5E, 0x5C, 0x5A, 0x58, 0x56,
    0x54, 0x52, 0x50, 0x50, 0x4E, 0x4C, 0x4A, 0x48, 0x46, 0x46, 0x44, 0x42, 0x40, 0x3E, 0x3E, 0x3C,
    0x3A, 0x38, 0x38, 0x36, 0x34, 0x32, 0x32, 0x30, 0x2E, 0x2E, 0x2C, 0x2A, 0x28, 0x28, 0x26, 0x24,
    0x24, 0x22, 0x20, 0x20, 0x1E, 0x1E, 0x1C, 0x1A, 0x1A, 0x18, 0x18, 0x16, 0x14, 0x14, 0x12, 0x12,
    0x10, 0x0E, 0x0E, 0x0C, 0x0C, 0x0A, 0x0A, 0x08, 0x08, 0x06, 0x06, 0x04, 0x04, 0x02, 0x02, 0x00,
];

/// `Fn = RECIPS Fx`: sign of `x`, exponent `-e - 1`, 8-bit seed fraction of the 7 MSBs.
pub(super) fn frecips(a: P) -> P {
    a.map(|w| {
        let x = val(w);
        if x == 0.0 {
            return f32::INFINITY.to_bits();
        }
        let bits = x.to_bits();
        let e = ((bits >> 23) & 0xFF) as i32 - 127;
        if e > 125 {
            return 0;
        }
        let seed = f32::from(RECIPS_SEED[((bits >> 16) & 0x7F) as usize]);
        let mag = 2f32.powi(-e - 1) * (1.0 + seed / 256.0);
        (if x < 0.0 { -mag } else { mag }).to_bits()
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    struct Flat(Vec<u32>);

    impl Mem for Flat {
        fn rd(&self, addr: u32) -> u32 {
            self.0[addr as usize]
        }
        fn wr(&mut self, addr: u32, word: u32) {
            self.0[addr as usize] = word;
        }
    }

    #[test]
    fn fixed_add_and_subtract_set_overflow_and_carry() {
        let flags = |e: Eff| match e {
            Eff::Fl4(an, az, av, ac) => (an, az, av, ac),
            _ => unreachable!(),
        };
        let (an, az, av, ac) = flags(fl_add_sub([0x7FFF_FFFF; 2], [1, 1], false));
        assert!(
            an[0] && !az[0] && av[0] && !ac[0],
            "signed overflow, no carry"
        );
        let (_, az, av, ac) = flags(fl_add_sub([5, 0], [5, 1], true));
        assert!(az[0] && ac[0] && !av[0], "x - x carries");
        assert!(!az[1] && !ac[1], "0 - 1 borrows");
        assert!(matches!(fl_int([0, 1]), Eff::Fl2(_, az) if az == [true, false]));
        assert!(matches!(fl_float([0, 1.0f32.to_bits()]), Eff::Fl2(an, _) if an == [false; 2]));
    }

    #[test]
    fn conditions_pick_per_element() {
        let mut pe = Pe::new(Flat(vec![0; 8]), 0, 4);
        pe.az = [true, false];
        pe.av = [false, true];
        assert_eq!(pe.cond(Cond::Eq, [1, 1], [9, 9]), [9, 1]);
        assert_eq!(pe.cond(Cond::Ne, [1, 1], [9, 9]), [1, 9]);
        assert_eq!(pe.cond(Cond::Av, [1, 1], [9, 9]), [1, 9]);
        assert_eq!(pe.cond_lane(Cond::Ac, 0, 3, 4), 3);
    }

    #[test]
    fn extrema_and_bit_fields_follow_the_shifter() {
        let w = |x: u32| [x; 2];
        assert_eq!(swap([1, 2]), [2, 1]);
        assert_eq!(imax(w(5), w((-3i32) as u32)), w(5));
        assert_eq!(imin(w(5), w((-3i32) as u32)), w((-3i32) as u32));
        assert_eq!(fext_p(w(0xABCD_1234), w(22), w(10), w(0)), w(0x2AF));
        assert_eq!(fext_p(w(0x8000_0000), w(22), w(10), w(1)), w(0xFFFF_FE00));
        assert_eq!(fdep_p(w(0x3FF), w(22), w(9)), w(0x1FF << 22));
    }

    #[test]
    fn shifts_follow_the_sign_of_the_amount() {
        assert_eq!(ishl([3, 3], [1, 40]), [6, 0]);
        assert_eq!(ishl([8, 8], [(-1i32) as u32, (-40i32) as u32]), [4, 0]);
    }

    #[test]
    fn clip_pass_average_and_extrema() {
        let f = |x: f32| [x.to_bits(); 2];
        assert_eq!(fclip(f(2.0), f(-1.0))[0], 1.0f32.to_bits());
        assert_eq!(fclip(f(-3.0), f(1.0))[0], (-1.0f32).to_bits());
        assert_eq!(favg(f(1.0), f(2.0))[0], 1.5f32.to_bits());
        assert_eq!(fpass(f(0.25)), f(0.25));
        assert_eq!(isub([5, 1], [3, 2]), [2, u32::MAX]);
    }

    #[test]
    fn recips_is_the_seed_of_the_reciprocal() {
        let r = val(frecips([4.0f32.to_bits(); 2])[0]);
        assert!((r - 0.25).abs() < 0.25 / 128.0, "{r}");
        let n = val(frecips([(-1.5f32).to_bits(); 2])[0]);
        assert!((n + 1.0 / 1.5).abs() < 0.01, "{n}");
        assert_eq!(frecips([0.0f32.to_bits(); 2])[0], f32::INFINITY.to_bits());
    }

    #[test]
    fn pre_modify_addresses_wrap_in_a_circular_buffer_like_immediate_modifies() {
        let mut pe = Pe::new(Flat(vec![0; 8]), 0, 4);
        pe.m[3] = 7;
        assert_eq!(pe.plain(1, 3), 11, "L = 0: a plain add");
        (pe.b[6], pe.i[6], pe.l[6], pe.m[6]) = (16, 23, 8, 2);
        assert_eq!(pe.plain(6, 6), 17, "23 + 2 = 25 >= 24: 25 - 8");
        (pe.b[6], pe.i[6], pe.l[6]) = (16, 23, 8);
        assert_eq!(pe.dmodi(6, 2), 17, "23 + 2 = 25 >= 24: 25 - 8");
    }
}
